            );
          }
          if (from < 39) {
            await _addColumnIfMissing(
              "memory_episodes ADD COLUMN topic_id TEXT NOT NULL DEFAULT '__ungrouped__'",
            );
            await customStatement(
              "INSERT OR IGNORE INTO memory_entities("
              "id, name, category, status, relationship_to_user, "
              "fragment_count, generated_by_version, user_corrected, "
              "schema_version"
              ") VALUES ("
              "'user_self', 'user_self', 'self', 'seed', 'self', "
              "0, 'migration.v39', 0, 1"
              ")",
            );
            await customStatement(
              "UPDATE memory_episodes "
              "SET topic_id = primary_entity_id "
              "WHERE topic_id = '__ungrouped__'",
            );
            await customStatement(
              "UPDATE memory_episodes "
              "SET primary_entity_id = 'user_self' "
              "WHERE primary_entity_id NOT IN ("
              "SELECT id FROM memory_entities"
              ")",
            );
          }
        },
        beforeOpen: (OpeningDetails details) async {
          // Defensive backfill: some devices upgraded to v43 via the earlier
          // commit 73041e19 (which only added dev-room model columns) and
          // therefore never received the transfer_direction column that was
          // later appended to the same `if (from < 43)` block by 89b02d84.
          // The v44 migration should fix new upgrades, but this hook also
          // repairs already-broken databases on the next open — regardless
          // of their user_version — so existing installs self-heal without
          // needing a wipe/reinstall.
          try {
            final cols = await customSelect(
              'PRAGMA table_info(ai_finance_ledger)',
            ).get();
            final hasCol = cols.any((row) {
              final name = row.read<String>('name');
              return name == 'transfer_direction';
            });
            if (!hasCol) {
              await customStatement(
                'ALTER TABLE ai_finance_ledger ADD COLUMN transfer_direction TEXT',
              );
              _logger.info(
                  'beforeOpen: backfilled missing ai_finance_ledger.transfer_direction column');
            }
          } catch (e) {
            // Table may not exist on very old schemas; ignore — the v44
            // migration / createAll handles fresh table creation.
            _logger.warning('beforeOpen: transfer_direction backfill skipped: $e');
          }
        },
      );

  Future<void> _createMemoryV3Tables(Migrator m) async {
    // 用户确认资料层
    await m.createTable(memoryCards);
    await m.createTable(memoryCardSources);
    await m.createTable(memoryCardStructuredFields);
    await m.createTable(memoryCardRelations);
    await m.createTable(memoryCardAssets);
    // Dreaming 自动产物层
    await m.createTable(memoryFragments);
    await m.createTable(memoryEntities);
    await m.createTable(memoryEntityLinks);
    await m.createTable(memoryEpisodes);
    await m.createTable(memorySagas);
    await m.createTable(memorySagaSnapshots);
    // 原始资料与审计层
    await m.createTable(assets);
    await m.createTable(assetAnalysis);
    await m.createTable(userCorrections);
    await m.createTable(memoryCardOperations);
    // 索引 / 召回辅助
    await m.createTable(memoryRecallEvents);
    await m.createTable(memoryEmbeddings);
    await m.createTable(projectMemoryItems);
    await m.createTable(projectMemorySources);

    // Topic Thread tables
    await m.createTable(topicThreads);
    await m.createTable(topicThreadSessions);

    await _createMemoryV3Indices();
  }

